                                                                                                                                                                                                                  
  CREATE TABLE "JW_WORKBENCH"                                                                                                                                                                      
   (	"WORKBENCH_ID" NUMBER(20,0) GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 222 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,     
	"TENANT_ID" NUMBER(20,0),                                                                                                                                                                                        
	"CREATED_BY" NVARCHAR2(256),                                                                                                                                                                                     
	"CREATION_DATE" DATE DEFAULT sysdate NOT NULL ENABLE,                                                                                                                                                            
	"UPDATED_BY" NVARCHAR2(256),                                                                                                                                                                                     
	"UPDATE_DATE" DATE DEFAULT sysdate NOT NULL ENABLE,                                                                                                                                                              
	"WORKBENCH_NAME" VARCHAR2(255) NOT NULL ENABLE,                                                                                                                                                                  
	"BLACKBOARD_CATEGORIES" VARCHAR2(1000),                                                                                                                                                                          
	"IS_ENABLE" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE,                                                                                                                                                               
	"DEL_FLAG" NUMBER(1,0) DEFAULT 0 NOT NULL ENABLE,                                                                                                                                                                
	"SCOPE_TYPE" VARCHAR2(15) DEFAULT 'ALL' NOT NULL ENABLE,                                                                                                                                                         
	"SORT_NUM" NUMBER(10,0) DEFAULT 1000 NOT NULL ENABLE,                                                                                                                                                            
	"TEMPLATE_ID" NUMBER(20,0) DEFAULT 1 NOT NULL ENABLE,                                                                                                                                                            
	"SLIDER_TIME" NUMBER(*,0) DEFAULT 2000,                                                                                                                                                                          
	"BLACKBOARD_TYPE_IS_TILE" NUMBER(1,0) DEFAULT 1,                                                                                                                                                                 
	 PRIMARY KEY ("WORKBENCH_ID")                                                                                                                                                                                    
  USING INDEX  ENABLE                                                                                                                                                                                             
   ) ;                                                                                                                                                                                                            

